command:
C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe -NoProfile -Command "`$u='http://127.0.0.1:3080/v3/projects/CampusNetwork_04/nodes/PE2/command?cmd=display%20interface'
`$lines=(Invoke-RestMethod -Uri `$u).output -split '\r?\n'
`$take=`$false
foreach(`$l in `$lines) {
 if(`$l -match 'current state .*ifindex') {`$take=(`$l -match '^Ethernet1/0/(1|2) current state')}
 if(`$take -and `$l -match '(^Ethernet1/0/(1|2) current state|^Line protocol|^Description|Last 300 seconds|^    Input:|^    Output:|unicast|errors|drops)') {Write-Output `$l}
}"
